CREATE TABLE t1 (x INTEGER); INSERT INTO t1 VALUES(1); CREATE TABLE t2 (z TEXT); INSERT INTO t2 VALUES('some value'); CREATE TABLE t3(w TEXT); INSERT INTO t3 VALUES('some other value');
SELECT ( SELECT 1 FROM t2 LEFT JOIN (SELECT x AS v FROM t3) ON 500=v WHERE (v OR FALSE) ) FROM t1;
SELECT ( SELECT 1 FROM t2 LEFT JOIN (SELECT x AS v FROM t3) ON 500=v WHERE (v) ) FROM t1;
SELECT ( SELECT 1 FROM t2 LEFT JOIN (SELECT x AS v FROM t3) ON 500=v WHERE (v OR FALSE) ) FROM t1;
DROP TABLE t1; DROP TABLE t2; DROP TABLE t3; CREATE TABLE t1(x TEXT, y INTEGER); INSERT INTO t1(x,y) VALUES(NULL,-2),(NULL,1),('0',2); CREATE TABLE t2(z INTEGER); INSERT INTO t2(z) VALUES(2),(-2); CREATE VIEW t3 AS SELECT z, (SELECT count(*) FROM t1) AS w FROM t2; SELECT * FROM t1 LEFT JOIN t3 ON y=z;
DROP TABLE t1; DROP TABLE t2; DROP VIEW t3; CREATE TABLE t1(a INTEGER PRIMARY KEY); WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<100) INSERT INTO t1(a) SELECT n FROM c; CREATE VIEW t2(b) AS SELECT a FROM t1;
